schema_ddl:
CREATE TABLE clienti (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome TEXT NOT NULL, codice_fiscale TEXT UNIQUE NOT NULL);

CREATE TABLE polizze (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente_id INT REFERENCES clienti(id), premio NUMERIC(12,2) CHECK (premio >= 0), data_inizio DATE NOT NULL, data_fine DATE NOT NULL, CHECK (data_fine > data_inizio));

CREATE TABLE tipologie_polizza (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, descrizione TEXT NOT NULL);

CREATE TABLE polizze_dettaglio (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, polizza_id INT REFERENCES polizze(id), tipologia_id INT REFERENCES tipologie_polizza(id));

CREATE TABLE sinistri (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, polizza_id INT REFERENCES polizze(id), data_sinistro TIMESTAMP NOT NULL, importo_liquidato NUMERIC(12,2) DEFAULT 0);

CREATE TABLE sinistri_archivio (id INT PRIMARY KEY, polizza_id INT, data_sinistro TIMESTAMP, importo_liquidato NUMERIC(12,2));

CREATE TABLE agenti (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome_agente TEXT NOT NULL);

CREATE TABLE mandati (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agente_id INT REFERENCES agenti(id), polizza_id INT REFERENCES polizze(id));

CREATE TABLE pagamenti (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, polizza_id INT REFERENCES polizze(id), importo NUMERIC(12,2) NOT NULL, data_pagamento DATE DEFAULT CURRENT_DATE);

CREATE TABLE rimborsi (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sinistro_id INT REFERENCES sinistri(id), importo_rimborsato NUMERIC(12,2) NOT NULL, data_rimborso DATE DEFAULT CURRENT_DATE);
